import{_ as t,o,c as d,a3 as c}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"查询","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"查询 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/query"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/query"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/query"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/query"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/query"}]]},"headers":[],"relativePath":"zh/clice/cli/query.md","filePath":"zh/clice/cli/query.md","lastUpdated":1790004299000}'),r={name:"zh/clice/cli/query.md"};function l(i,e,a,n,s,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="查询" tabindex="-1">查询 <a class="header-anchor" href="#查询" aria-label="Permalink to &quot;查询&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>clice query</code> 向持久化索引提出一个结构化的问题，并把答案以 JSON 形式打印到 stdout——供那些不想说 LSP、又想拿到语言服务器所掌握事实的脚本和 coding agent 使用。它直接从磁盘读取索引，正是 <code>clice index</code> 构建、编辑器会话持续更新的那一份，因此编辑器开着时它照常工作，编辑器没开时也不需要服务器。</p><p><strong>用法</strong>：<code>clice query --method &lt;question&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--fresh] [question options]</code></p><h2 id="支持的问题" tabindex="-1">支持的问题 <a class="header-anchor" href="#支持的问题" aria-label="Permalink to &quot;支持的问题&quot;">​</a></h2><ul><li><code>symbolSearch --query &lt;query&gt; [--limit &lt;n&gt;] [--kind &lt;Kind,...&gt;]</code> 列出名称查询匹配到的符号，最佳匹配排在最前，并附上各符号的种类、文件、行号、所属容器和 id。</li><li><code>definition</code>、<code>readSymbol</code>、<code>references [--include-declaration]</code>、<code>callGraph [--direction callers|callees|both]</code> 和 <code>typeHierarchy [--direction supertypes|subtypes|both]</code> 回答关于单个符号的问题。符号由 <code>--name &lt;query&gt;</code>（一个名称查询，可用 <code>--path</code> 进一步缩小范围）、<code>--symbol &lt;id&gt;</code>（此前的答案所带的 <code>#&lt;hex&gt;</code> id）或 <code>--path &lt;file&gt; --line &lt;n&gt;</code>（该行上定义的符号）指定。多个符号叫同一个名字时，会把它们一一列出并要求改用 id；没有符号与该名称完全一致时，同样会列出最接近的匹配。</li><li><code>documentSymbols --path &lt;file&gt;</code> 给出该文件的大纲。</li><li><code>compileCommand --path &lt;file&gt;</code> 给出编辑器编译该文件时会使用的命令，以及它的来源：文件自身的数据库条目、头文件的宿主源文件、规则的默认命令、根据邻近翻译单元推断出的命令，或内置的回退命令。</li><li><code>projectFiles [--filter all|source|header|module]</code> 列出构建涉及的文件；<code>fileDeps --path &lt;file&gt; [--direction includes|includers|both] [--depth &lt;n&gt;]</code> 和 <code>impactAnalysis --path &lt;file&gt;</code> 则沿包含关系图查询。</li></ul><p>问题中的路径可以相对于工作区，也可以是绝对路径，答案中的路径一律是绝对路径；行号从 1 开始。</p><h2 id="名称查询" tabindex="-1">名称查询 <a class="header-anchor" href="#名称查询" aria-label="Permalink to &quot;名称查询&quot;">​</a></h2><p>一条名称查询就是一个字符串。空格分隔其中的各个词项，引号和尖括号里的空格则原样保留。其中一项指明符号，其余各项用来收窄答案。</p><table tabindex="0"><thead><tr><th>查询</th><th>匹配结果</th></tr></thead><tbody><tr><td><code>foo</code></td><td>名称能按单词对齐、把 <code>foo</code> 作为子序列匹配上的符号——<code>LinLis</code> 找到 <code>LinkedList</code>，<code>up</code> 找到 <code>unique_ptr</code>——名称完全一致的排在最前，其次是以查询开头的名称，然后才是其余的；查询有六个及以上字母时，还会找到相差一处拼写错误的名称，排在最后</td></tr><tr><td><code>&quot;foo&quot;</code></td><td>完整的名称，区分大小写</td></tr><tr><td><code>foo*</code>、<code>*_test</code>、<code>get?Name</code></td><td>该 glob 模式匹配上的名称；模式中一旦出现大写字母就区分大小写</td></tr><tr><td><code>ns::Foo::bar</code></td><td>位于某个容器内的符号，且该容器链按此顺序列出 <code>ns</code> 和 <code>Foo</code>，其间和两端允许有别的容器</td></tr><tr><td><code>::ns::Foo::bar</code></td><td>恰好位于该容器内的符号</td></tr><tr><td><code>ns::*</code>、<code>ns::**</code></td><td>该容器的成员；以及它之下的全部内容</td></tr><tr><td><code>Widget&lt;int&gt;</code></td><td>以这些实参写出的那个特化</td></tr><tr><td><code>#1a2b3c</code></td><td>具有该 id 的符号</td></tr><tr><td><code>src/a.cpp:120</code></td><td>在该行上定义的符号</td></tr><tr><td><code>src/a.cpp:120:8</code></td><td>该光标处的符号，行号从 1 开始，列号按字节计</td></tr><tr><td><code>kind:function,method</code></td><td>只保留这些种类（<code>--kind</code> 的作用相同）</td></tr><tr><td><code>path:src/index/</code></td><td>在该目录下声明的符号；只写文件名时按名称匹配，其他路径则按尾部匹配</td></tr></tbody></table><h2 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h2><p>每个答案都是一个 JSON 对象：成功时是 <code>{&quot;result&quot;: ..., &quot;stale&quot;: [...]}</code>；问题无法回答时（符号不存在、文件不存在、选项无效）是 <code>{&quot;error&quot;: &quot;...&quot;, &quot;stale&quot;: [...]}</code>，退出码为 1。</p><p><code>stale</code> 列出答案不得不略过其数据行的文件：它们在磁盘上的内容已经与建立索引时不一致，索引为它们保存的位置会指向移动过的文本。仅因所包含的头文件发生变化的文件，仍用它上一次的数据行作答。定义位于已过期文件中的符号会被报告为未找到，并给出文件名，这样读者就能区分“不存在”和“尚未建立索引”。只有答案查阅过的文件才会被检查：在文件建立索引之后新增的符号只会缺席，因为没有任何数据行指向那个文件——要询问磁盘的当前状态，请用 <code>--fresh</code>。索引从不读取编辑器中未保存的缓冲区：它描述的是磁盘上的内容。</p><p><code>--fresh</code> 会在作答前把索引更新到与磁盘一致：若编辑器会话正打开着该工作区，由它的服务器执行这轮索引；否则由命令自己运行索引器，尚无索引时从零开始建立。两种情况下都只重新编译输入发生变化的翻译单元。不加 <code>--fresh</code> 时，没有索引的工作区只会返回错误。</p>',14)])])}const g=t(r,[["render",l]]);export{u as __pageData,g as default};
